body.script:
(function(){var f='all';
  function apply(){Array.prototype.forEach.call(document.querySelectorAll('tr.p'),function(r){var ok=f==='all'||(f==='need'&&r.getAttribute('data-need')==='1')||(f===r.getAttribute('data-kind'));r.hidden=!ok;if(!ok){r.nextElementSibling.hidden=true;}});}
  document.addEventListener('click',function(e){var c=e.target.closest?e.target.closest('.chip'):null;
    if(c){f=c.getAttribute('data-f');Array.prototype.forEach.call(document.querySelectorAll('.chip'),function(x){x.classList.toggle('on',x===c);});apply();return;}
    var mk=e.target.closest?e.target.closest('.mkbtn'):null;if(mk){e.stopPropagation();openMo(mk);return;}
    var r=e.target.closest?e.target.closest('tr.p'):null;if(r){r.nextElementSibling.hidden=!r.nextElementSibling.hidden;}});
  function rpc(model,method,args,kwargs){return fetch('/web/dataset/call_kw',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',method:'call',params:{model:model,method:method,args:args,kwargs:kwargs||{}}})}).then(function(r){return r.json();}).then(function(j){if(j.error){throw new Error((j.error.data&&j.error.data.message)||'It did not work.');}return j.result;});}
  var ov=document.getElementById('ov'),$=function(i){return document.getElementById(i);},run=null;
  function show(title,msg,okText,mo,fn){$('dt').textContent=title;$('dm').textContent=msg||'';$('dok').textContent=okText;$('dok').disabled=false;$('dok').hidden=false;$('dmo').hidden=!mo;$('derr').hidden=true;run=fn;ov.hidden=false;}
  function fail(e){$('derr').textContent=e.message;$('derr').hidden=false;$('dok').disabled=false;}
  function openMo(b){$('dq').value=b.getAttribute('data-need');$('dc').value=b.getAttribute('data-co');if($('dp')){$('dp').value='';}
    var nt=b.getAttribute('data-note')||'';show('Make '+b.getAttribute('data-name'),nt?'Order note (copied onto the manufacturing order):\n'+nt:'','Create the manufacturing order',true,function(){var co=+$('dc').value,q=parseFloat($('dq').value)||0;if(q<=0){fail(new Error('Enter a quantity.'));return;}
      var vals={product_id:+b.getAttribute('data-pid'),product_qty:q,company_id:co,picking_type_id:co===3?77:55};if($('dp')){vals.x_pin=$('dp').value;}if(nt){vals.x_order_note=nt;}
      rpc('mrp.production','create',[vals],{context:{allowed_company_ids:[co,co===3?1:3],default_company_id:co}}).then(function(id){location.href='/odoo/action-1319/'+id;}).catch(fail);});}
  $('dno').addEventListener('click',function(){ov.hidden=true;if(run===null){location.reload();}});
  $('dok').addEventListener('click',function(){if(run){$('dok').disabled=true;$('derr').hidden=true;run();}});
  var bb=$('bringbtn');if(bb){bb.addEventListener('click',function(){var own=$('own'),items=[],txt=[];
    Array.prototype.forEach.call(own.querySelectorAll('li'),function(li){items.push([+li.getAttribute('data-pid'),parseFloat(li.getAttribute('data-qty'))]);txt.push(li.textContent.replace(/\s*\(SMBF needs.*$/,'').replace(/\s+/g,' ').trim());});
    show('Bring from smbfoods to SMBF?',txt.join('\n')+'\n\nThis posts one invoice in smbfoods and one bill in SMBF.','Yes, bring them',false,function(){
      rpc('ir.actions.server','run',[[+own.getAttribute('data-ra')]],{context:{smb_bring:items,allowed_company_ids:[3,1]}}).then(function(res){$('dt').textContent='Done';$('dm').textContent=(res&&res.params&&res.params.message)||'Done.';$('dok').hidden=true;$('dno').textContent='Close';run=null;}).catch(fail);});});}
})();
